#!/usr/bin/env python3
"""Generate docs/DATA_MODEL.md (data dictionary) from the payload models and the SQL schema."""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))


def main() -> int:
    from ris.domain.enums import LABELS, RecordKind, Verification, label
    from ris.domain.registry import REGISTRY, field_metas

    out = ["# Data model and dictionary", "",
           "Generated by `scripts/gen_data_dictionary.py` from `ris/domain/models.py`, `ris/domain/registry.py` and "
           "`migrations/`. Do not edit by hand.", "",
           "## Storage", "",
           "Each workspace is one SQLite database (`ris.db`, rollback journal, `synchronous=FULL`). Every profile item "
           "is a row in `records`: a stable id, kind, optional parent, sort order, verification, confidentiality, "
           "origin, revision, checksum, soft-delete tombstone and a JSON payload validated by the model for its kind. "
           "Other tables: `records_fts` (full-text search), `variant_versions` (immutable resume versions), `exports` "
           "(export log with SHA-256), `settings`, `audit_log` (field names only, never values), `sync_base` and "
           "`sync_conflicts`.", "",
           "Envelope fields shared by every record:", "",
           "| Field | Meaning |", "|---|---|",
           "| verification | " + "; ".join(LABELS[Verification].values()) + " |",
           "| confidentiality | Public; Approved for professional use; Requires review; Confidential |",
           "| origin | Entered manually, Imported, Preliminary (pre-populated), Fictional sample, Generated, "
           "Synchronised |",
           "| revision / checksum | Optimistic concurrency and sync change detection |", "",
           "Fields marked **private** never appear in documents unless explicitly selected (bio-data particulars).", ""]
    for kind, info in REGISTRY.items():
        model = info.model
        out.append(f"## {label(kind)} (`{kind.value}`)")
        out.append("")
        meta = []
        if info.parents:
            meta.append("child of " + ", ".join(f"`{p.value}`" for p in info.parents))
        if info.singleton:
            meta.append("one per workspace")
        meta.append("fact (verification applies)" if info.is_fact else "working record (not a fact)")
        meta.append(f"default classification for manual entries: {label(info.default_confidentiality)}")
        out.append("; ".join(meta).capitalize() + ".")
        doc = (model.__doc__ or "").strip()
        if doc and not doc.startswith("Base class"):
            out.append("")
            out.append(doc.splitlines()[0])
        out.append("")
        out.append("| Field | Title | Type / choices | Group | Notes |")
        out.append("|---|---|---|---|---|")
        for m in field_metas(model, include_hidden=True):
            if m.enum_type is not None:
                typ = "one of: " + ", ".join(f"`{e.value}`" for e in m.enum_type)
            else:
                ann = model.model_fields[m.name].annotation
                typ = getattr(ann, "__name__", str(ann)).replace("typing.", "")
                typ = {"str": "text", "bool": "yes/no", "int": "integer", "float": "number"}.get(typ, typ)
                if m.widget in ("tags", "list", "paragraphs"):
                    typ = "list of text"
                elif m.widget == "date":
                    typ = "partial date (YYYY, YYYY-MM, YYYY-MM-DD)"
                elif m.widget in ("ref", "refs"):
                    typ = f"reference to `{m.ref_kind}`" + ("s" if m.widget == "refs" else "")
            notes = []
            if m.private:
                notes.append("**private**")
            if m.hidden:
                notes.append("system-managed")
            if m.help:
                notes.append(m.help.replace("|", "/"))
            out.append(f"| `{m.name}` | {m.title} | {typ} | {m.group} | {'; '.join(notes)} |")
        out.append("")
    del RecordKind
    (ROOT / "docs" / "DATA_MODEL.md").write_text("\n".join(out) + "\n", encoding="utf-8")
    print("docs/DATA_MODEL.md written")
    return 0


if __name__ == "__main__":
    sys.exit(main())
